import sqlite3
from html.parser import HTMLParser
from urllib.parse import urljoin

RATING = {"One": 1, "Two": 2, "Three": 3, "Four": 4, "Five": 5}


def normalisasi_harga(teks):
    if not isinstance(teks, str):
        return None
    t = teks.strip()
    if t.startswith("Rp"):
        t = t[2:].replace(".", "").replace(",", ".")
    else:
        t = t.lstrip("£$").replace(",", "")
    try:
        return float(t.strip())
    except ValueError:
        return None


class KatalogParser(HTMLParser):
    def __init__(self, url_dasar):
        super().__init__()
        self.url_dasar = url_dasar
        self.buku = []
        self.sekarang = None
        self.isi = None

    def handle_starttag(self, tag, attrs):
        a = dict(attrs)
        kelas = (a.get("class") or "").split()
        if tag == "article" and "product_pod" in kelas:
            self.sekarang = {"judul": None, "url": None, "harga": None, "rating": None, "tersedia": False}
        elif self.sekarang is None:
            return
        elif tag == "a" and a.get("title"):
            self.sekarang["judul"] = a["title"].strip()
            self.sekarang["url"] = urljoin(self.url_dasar, a.get("href", ""))
        elif tag == "p" and "star-rating" in kelas:
            self.sekarang["rating"] = next((RATING[k] for k in kelas if k in RATING), None)
        elif tag == "p" and "price_color" in kelas:
            self.isi = "harga"
            self.sekarang["harga"] = ""
        elif tag == "p" and "availability" in kelas:
            self.isi = "stok"
            self.sekarang["stok"] = ""

    def handle_data(self, data):
        if self.sekarang is not None and self.isi == "harga":
            self.sekarang["harga"] += data
        elif self.sekarang is not None and self.isi == "stok":
            self.sekarang["stok"] += data

    def handle_endtag(self, tag):
        if tag == "p":
            self.isi = None
        elif tag == "article" and self.sekarang is not None:
            b = self.sekarang
            self.sekarang = None
            harga = normalisasi_harga(b["harga"])
            if not b["judul"] or harga is None:
                return  # data kotor: lewati satu buku, jangan hentikan semuanya
            self.buku.append({
                "judul": b["judul"],
                "url": b["url"],
                "harga": harga,
                "rating": b["rating"],
                "tersedia": b.pop("stok", "").strip().lower().startswith("in stock"),
            })


def parse_katalog(html, url_dasar):
    p = KatalogParser(url_dasar)
    p.feed(html)
    p.close()
    return p.buku


def siapkan_db():
    conn = sqlite3.connect(":memory:")
    conn.execute("""CREATE TABLE buku (
        url TEXT PRIMARY KEY, judul TEXT NOT NULL, harga REAL,
        rating INTEGER, tersedia INTEGER)""")
    conn.execute("""CREATE TABLE riwayat_harga (
        url TEXT NOT NULL, harga REAL, waktu TEXT NOT NULL)""")
    return conn


def simpan(conn, daftar, waktu):
    hitung = {"baru": 0, "berubah": 0, "tetap": 0}
    with conn:
        for b in daftar:
            lama = conn.execute("SELECT harga FROM buku WHERE url = ?", (b["url"],)).fetchone()
            conn.execute("""
                INSERT INTO buku (url, judul, harga, rating, tersedia) VALUES (?, ?, ?, ?, ?)
                ON CONFLICT(url) DO UPDATE SET
                  judul = excluded.judul, harga = excluded.harga,
                  rating = excluded.rating, tersedia = excluded.tersedia
            """, (b["url"], b["judul"], b["harga"], b["rating"], int(b["tersedia"])))
            if lama is None:
                hitung["baru"] += 1
            elif lama[0] != b["harga"]:
                hitung["berubah"] += 1
            else:
                hitung["tetap"] += 1
                continue
            conn.execute("INSERT INTO riwayat_harga VALUES (?, ?, ?)", (b["url"], b["harga"], waktu))
    return hitung


def laporan(conn):
    hasil = []
    for url, judul, baru in conn.execute("SELECT url, judul, harga FROM buku ORDER BY url"):
        dua = conn.execute(
            "SELECT harga FROM riwayat_harga WHERE url = ? ORDER BY waktu DESC, rowid DESC LIMIT 2", (url,)
        ).fetchall()
        if len(dua) == 2:
            lama = dua[1][0]
            hasil.append({"judul": judul, "lama": lama, "baru": baru, "selisih": round(baru - lama, 2)})
    return sorted(hasil, key=lambda x: abs(x["selisih"]), reverse=True)


