def jeda_backoff(percobaan, dasar=1, maks=30):
    return min(maks, dasar * 2 ** percobaan)


def ambil_dengan_retry(ambil, url, maks_coba, tidur):
    for coba in range(maks_coba):
        try:
            respons = ambil(url)
        except TimeoutError:
            respons = None
        if respons is not None and respons["status"] != 429 and respons["status"] < 500:
            return respons
        if coba == maks_coba - 1:
            break
        tunggu = (respons or {}).get("headers", {}).get("Retry-After", "")
        if respons is not None and respons["status"] == 429 and tunggu.isdigit():
            tidur(int(tunggu))
        else:
            tidur(jeda_backoff(coba))
    return None


