def cocok_kolom(pola, nilai):
    for bagian in pola.split(","):
        if bagian == "*":
            return True
        if bagian.startswith("*/"):
            if nilai % int(bagian[2:]) == 0:
                return True
        elif int(bagian) == nilai:
            return True
    return False


def cocok_cron(ekspresi, waktu):
    kolom = ekspresi.split()
    if len(kolom) != 5:
        raise ValueError("ekspresi cron harus 5 kolom")
    hari = (waktu.weekday() + 1) % 7  # cron: 0 = Minggu, Python: 0 = Senin
    nilai = [waktu.minute, waktu.hour, waktu.day, waktu.month, hari]
    return all(cocok_kolom(p, n) for p, n in zip(kolom, nilai))


